ALTER TABLE "MerchantConfig" ADD COLUMN "application" JSONB NOT NULL DEFAULT '{}', ADD COLUMN "applicationState" TEXT NOT NULL DEFAULT 'Draft', ADD COLUMN "applicationVersion" INTEGER NOT NULL DEFAULT 1, ADD COLUMN "riskPolicy" JSONB NOT NULL DEFAULT '{}', ADD COLUMN "liveScope" JSONB NOT NULL DEFAULT '{}';
CREATE TABLE "MerchantRiskDecision" ("id" TEXT PRIMARY KEY, "intentId" TEXT NOT NULL REFERENCES "PaymentIntent"("id"), "policyVersion" TEXT NOT NULL, "decision" TEXT NOT NULL, "reasons" JSONB NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "MerchantRiskDecision_intentId_createdAt_idx" ON "MerchantRiskDecision"("intentId","createdAt");
CREATE TABLE "MerchantReservation" ("intentId" TEXT PRIMARY KEY REFERENCES "PaymentIntent"("id"), "orgId" TEXT NOT NULL REFERENCES "Organization"("id"), "environment" TEXT NOT NULL, "asset" TEXT NOT NULL, "day" TEXT NOT NULL, "amount" DECIMAL(50,0) NOT NULL CHECK ("amount">0), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "MerchantReservation_orgId_environment_asset_day_idx" ON "MerchantReservation"("orgId","environment","asset","day");
